CREATE ROLE atlas_failure_reader;
CREATE TABLE atlas_failure_secure(tenant name NOT NULL, payload text NOT NULL);
ALTER TABLE atlas_failure_secure ENABLE ROW LEVEL SECURITY;
CREATE POLICY atlas_security_policy ON atlas_failure_secure USING (tenant = current_user);
GRANT SELECT ON atlas_failure_secure TO atlas_failure_reader;
INSERT INTO atlas_failure_secure VALUES ('atlas_failure_reader', 'visible'), ('postgres', 'hidden');
SET ROLE atlas_failure_reader;
SELECT CASE WHEN count(*) = 1 AND min(payload) = 'visible'
  THEN 'ATLAS_SECURITY_PASS:operations.failure-injection'
  ELSE 'ATLAS_SECURITY_FAIL:operations.failure-injection' END
FROM atlas_failure_secure;
DO $$ BEGIN
  UPDATE atlas_failure_secure SET payload = 'forged';
  RAISE EXCEPTION 'update unexpectedly allowed';
EXCEPTION WHEN insufficient_privilege THEN
  RAISE NOTICE 'ATLAS_SECURITY_PASS:operations.failure-injection';
END $$;
RESET ROLE;

